                post_hook={
                    "sql": "create or replace table daniel_klein_db.maplemonk.daniel_klien_or_inventory_intermediate as select TO_DATE(date || \'-\' || year, \'DD-MON-YYYY\') AS inventory_date, upper(trim(sku)) as SKU, \'AMAZON OR\' as data_source, sum(ifnull(cast(trim(nullif(qty,\'\')) as int),0)) as inventory from daniel_klein_db.maplemonk.dk_s3_amazonor_inventory group by 1,2,3 union all select TO_DATE(date || \'-\' || year, \'DD-MON-YYYY\') AS inventory_date, upper(trim(sku)) as SKU, \'FLIPKART OR\' as data_source, sum(ifnull(cast(trim(nullif(qty,\'\')) as int),0)) as inventory from daniel_klein_db.maplemonk.dk_s3_flipkart_inventory group by 1,2,3 union all select TO_DATE(date || \'-\' || year, \'DD-MON-YYYY\') AS inventory_date, upper(trim(sku)) as SKU, \'MYNTRA OR\' as data_source, sum(ifnull(cast(trim(nullif(qty,\'\')) as int),0)) as inventory from daniel_klein_db.maplemonk.dk_s3_myntra_inventory group by 1,2,3 ; create or replace table daniel_klein_db.maplemonk.daniel_klien_or_inventory as WITH DateBounds AS ( SELECT MIN(date) AS min_date, current_date AS max_date FROM ( SELECT inventory_date as date FROM daniel_klein_db.maplemonk.daniel_klien_or_inventory UNION ALL (SELECT date(order_date) as date FROM daniel_klein_db.maplemonk.daniel_klein_DB_sales_consolidated where marketplace like \'%OR\') ) combined_dates ), DateGrid AS ( SELECT min_date AS date FROM DateBounds UNION ALL SELECT DATEADD(day, 1, date) FROM DateGrid WHERE date <= (SELECT max_date FROM DateBounds) ), DistinctEntities AS ( SELECT DISTINCT sku, data_source FROM daniel_klein_db.maplemonk.daniel_klien_or_inventory UNION (SELECT DISTINCT sku, marketplace as data_source FROM daniel_klein_db.maplemonk.daniel_klein_DB_sales_consolidated where marketplace like \'%OR\') ), DenseGrid AS ( SELECT d.date, e.sku, e.data_source FROM DateGrid d CROSS JOIN DistinctEntities e ), MergedData AS ( SELECT g.date, g.sku, g.data_source, i.inventory AS actual_inventory, COALESCE(s.sales_qty, 0) AS sales_qty FROM DenseGrid g LEFT JOIN daniel_klein_db.maplemonk.daniel_klien_or_inventory i ON g.date = i.inventory_date AND g.sku = i.sku AND g.data_source = i.data_source LEFT JOIN (SELECT sku, marketplace as data_source, date(order_date) as date, sum(ifnull(quantity,0)) as sales_qty FROM daniel_klein_db.maplemonk.daniel_klein_DB_sales_consolidated where marketplace like \'%OR\' group by 1,2,3 ) s ON g.date = s.date AND g.sku = s.sku AND g.data_source = s.data_source ), Islands AS ( SELECT *, COUNT(actual_inventory) OVER ( PARTITION BY sku, data_source ORDER BY date ) AS island_id FROM MergedData ), Calculations AS ( SELECT date, sku, data_source, actual_inventory, sales_qty, MAX(actual_inventory) OVER ( PARTITION BY sku, data_source, island_id ) AS base_inventory, SUM(CASE WHEN actual_inventory IS NULL THEN sales_qty ELSE 0 END) OVER ( PARTITION BY sku, data_source, island_id ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_sales FROM Islands ) SELECT date as inventory_date, sku, data_source, case when COALESCE(actual_inventory,(base_inventory - cumulative_sales))<0 then 0 else ifnull(COALESCE(actual_inventory,(base_inventory - cumulative_sales)),0) end AS inventory FROM Calculations WHERE base_inventory IS NOT NULL ORDER BY sku, data_source, date; create or replace table daniel_klein_db.maplemonk.daniel_klein_inventory_fact_items as WITH daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, upper(sku) as sku, upper(data_source) as data_source, SUM(ifnull(quantity,0)) AS daily_quantity, SUM(ifnull(selling_price,0)) as total_sales from daniel_klein_db.MAPLEMONK.daniel_klein_db_sales_consolidated s WHERE upper(data_source) in (\'AMAZON OR\',\'FLIPKART OR\',\'MYNTRA OR\',\'UNIWARE\') GROUP BY 1,2,3 ), daily_inventory_snapshot AS ( (SELECT TO_DATE(inventory_date) date_day, upper(SKU) sku, data_source, sum(cast(inventory as INT)) as inventory_that_day, CASE WHEN ifnull(sum(cast(inventory as INT)),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(sum(cast(inventory as INT)),0) < 4 THEN 1 ELSE 0 END AS is_oos FROM daniel_klein_db.maplemonk.daniel_klien_or_inventory i where sku <> \'#N/A\' GROUP BY 1,2,3 ORDER BY 1 DESC) union all (select date_day, sku, \'UNIWARE\' as data_source, cast(available_inventory as int) as inventory_that_day, CASE WHEN ifnull(cast(available_inventory as int),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(cast(available_inventory as int),0) < 4 THEN 1 ELSE 0 END AS is_oos from (select DATEADD(day, -1, CAST(left(_airbyte_emitted_at, 10) AS DATE)) as date_day, upper(\"Sku Code\") as sku, sum(cast(\"Total (Stock on hand)\" as int)) as available_inventory from daniel_klein_db.maplemonk.unicommerce_datatable_search_get_inventory_snapshot_export_full_refresh where type = \'GOOD_INVENTORY\' group by 1,2 ) ) ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, d.data_source FROM daily_inventory_snapshot AS d CROSS JOIN ( SELECT DATEADD(day, SEQ4(), \'2026-05-01\'::DATE) AS date_day FROM TABLE(GENERATOR(ROWCOUNT => 10000)) WHERE DATEADD(day, SEQ4(), \'2026-05-01\'::DATE) <= CURRENT_DATE() ) AS c ), sales_metrics AS ( SELECT a.date_day, a.sku, a.data_source, COALESCE(s.daily_quantity, 0) AS daily_quantity, COALESCE(total_sales, 0) as total_sales, COALESCE(i.has_inventory, 0) AS has_inventory_today, inventory_that_day, ifnull(i.is_oos, 1) AS is_oos_today, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS L14_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS L45_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS inventory_days_14, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS inventory_days_45, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS oos_days_7, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS oos_days_14, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS oos_days_30, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku,a.data_source ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS oos_days_45 FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku AND a.data_source = s.data_source LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku AND a.data_source = i.data_source order by 1 desc ) SELECT date_day as data_fetch_date, s.sku, s.data_source, p.name as product_name, p.product_category, p.product_sub_category, p.bucket_1, p.bucket_2, s.total_sales, s.daily_quantity, s.has_inventory_today, s.inventory_that_day as available_inventory, L7_day_sales sold_quantity_7_days, L14_day_sales sold_quantity_14_days, L30_day_sales sold_quantity_30_days, L45_day_sales sold_quantity_45_days, inventory_days_7, inventory_days_14, inventory_days_30, inventory_days_45, oos_days_7, oos_days_14, oos_days_30, oos_days_45, CASE WHEN data_source IN (\'UNIWARE\') THEN available_inventory ELSE 0 END AS mp_inventory, CASE WHEN data_source IN (\'AMAZON OR\', \'MYNTRA OR\', \'FLIPKART OR\') THEN available_inventory ELSE 0 END AS or_inventory FROM sales_metrics s LEFT JOIN (select upper(trim(dk_sku)) as sku, upper(trim(product_category)) as product_category, upper(trim(product_sub_category)) as product_sub_category, upper(trim(catalog_name)) as name, upper(trim(bucket_1)) as bucket_1, upper(trim(bucket_2)) as bucket_2 from DANIEL_KLEIN_DB.MAPLEMONK.Google_Sheet_SKU_MASTER qualify row_number() over (partition by upper(trim(dk_sku)) order by 1) = 1 ) p on upper(p.sku) = upper(s.sku) ;",
